import { cx } from "@/lib/cx";

export function Avatar({
  name,
  size = 40,
  className,
  alt,
}: {
  name: string;
  size?: number;
  className?: string;
  alt?: string;
}) {
  const safe = encodeURIComponent(name || "steve");
  return (
    // Avatar is generated by our own /api/avatar route — deterministic and offline-safe.
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/api/avatar/${safe}?size=${size}`}
      alt={alt ?? `${name}'s avatar`}
      width={size}
      height={size}
      loading="lazy"
      decoding="async"
      className={cx("rounded-md bg-surface-2 object-cover", className)}
      style={{ width: size, height: size, imageRendering: "pixelated" }}
    />
  );
}
